export const title = "Alert Setup Example (Intrusion Detection)";
export const html = "<h1>Alert Setup Example (Intrusion Detection)</h1>\n      <hr class=\"rule\" />\n      <p>To set up an event action for intrusion detection, access the AI Bridge and click <strong>Explore AI Apps &ndash; Intrusion Detection</strong> in the sidebar navigation.</p>\n      \n<div class=\"figure\">\n<div class=\"app-window\">\n  <div class=\"app-body\" style=\"min-height:auto;\">\n    <div class=\"app-sidebar-nav\">\n      <div class=\"grp\">Video</div>\n      <div class=\"item\">Video Source &#9656;</div>\n      <div class=\"item\">Event Rule Map</div>\n      <div class=\"item\">Output &#9656;</div>\n      <div class=\"grp\">System Settings</div>\n      <div class=\"item\">Network &#9656;</div>\n      <div class=\"item\">System &#9656;</div>\n      <div class=\"item\">License Management</div>\n      <div class=\"item\">Cloud Service</div>\n      <div class=\"grp\">App Settings</div>\n      <div class=\"item active\">Explore AI Apps</div>\n      <div class=\"item\">Active AI Apps &#9656;</div>\n      <div class=\"item\">System Event Settings</div>\n    </div>\n    <div class=\"app-main\">\n      <div style=\"text-align:right;font-size:11px;color:var(--text-muted);margin-bottom:10px;\">License in use</div>\n      <div style=\"background:#2f9e6e;color:#fff;padding:8px 14px;border-radius:6px 6px 0 0;font-weight:700;font-size:13px;\">Intrusion Detection</div>\n      <div style=\"border:1px solid var(--border);border-top:none;border-radius:0 0 6px 6px;padding:14px;margin-bottom:16px;\">\n        <div style=\"background:#eceff4;border-radius:6px;padding:18px;text-align:center;font-size:34px;\">&#9888;&#65039;&#128694;&#128694;&#128694;&#128104;&#128105;&#128103;</div>\n        <p style=\"font-size:12px;margin:10px 0;\">Detects people in restricted areas and sends alerts or configures other actions.</p>\n        <div style=\"display:flex;gap:8px;align-items:center;\">\n          <span class=\"badge\">8 CH</span><span class=\"badge\">Licensed</span>\n          <span style=\"margin-left:auto;font-size:11px;color:var(--text-muted);\">No rules in use</span>\n        </div>\n      </div>\n      <div style=\"background:#2f9e6e;color:#fff;padding:8px 14px;border-radius:6px 6px 0 0;font-weight:700;font-size:13px;\">Loitering / Left Object</div>\n      <div style=\"border:1px solid var(--border);border-top:none;border-radius:0 0 6px 6px;padding:14px;height:60px;\"></div>\n    </div>\n  </div>\n</div>\n<figcaption>Explore AI Apps &rarr; Intrusion Detection</figcaption>\n</div>\n\n      <p>Click the <strong>+ Add Rule</strong> button at the top right of the intrusion detection settings list to set up a new detection rule.</p>\n      <div class=\"figure\" style=\"max-width:150px;\"><span class=\"btn small primary\">+ Add Rule</span></div>\n\n      <h2>Basic Event Action Rule Settings</h2>\n      \n<div class=\"figure\">\n<div class=\"app-panel\" style=\"max-width:420px;\">\n  <div class=\"form-grid\" style=\"grid-template-columns:90px 1fr;\">\n    <span>Rule Name</span><input value=\"Rule #8516\" disabled>\n    <span>&#9432; Enable</span><span style=\"background:#2653d6;border-radius:10px;width:34px;height:18px;display:inline-block;position:relative;\"><span style=\"position:absolute;right:2px;top:2px;width:14px;height:14px;background:#fff;border-radius:50%;\"></span></span>\n  </div>\n</div>\n</div>\n\n      <ol>\n        <li>Enter a name in <strong>Rule Name</strong> to distinguish this rule. A random default value is pre-filled \u2014 edit it if needed. The action handler can also reference the name you enter here to identify which rule triggered it.</li>\n        <li>If you want the event action rule to be active as soon as it's created, turn on the <strong>Enable</strong> switch.</li>\n      </ol>\n\n      <h2>Event Settings</h2>\n      <ol>\n        <li>Click the <strong>Add</strong> button to configure an event.</li>\n      </ol>\n      \n<div class=\"figure\">\n<div class=\"app-panel\">\n  <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:10px;\"><strong style=\"font-size:13px;\">Event Settings</strong> <span class=\"btn small\">+ Add</span></div>\n  <table class=\"app-table\">\n    <tr><th>Video</th><th>Event Type</th><th>Event Name</th><th>UUID</th><th>Actions</th></tr>\n    <tr><td colspan=\"5\" style=\"text-align:center;color:var(--text-muted);\">\u2014</td></tr>\n  </table>\n</div>\n</div>\n\n      <ol start=\"2\">\n        <li>To set the detection area, use the <strong>video selection</strong> dropdown to the right of the event type to select which video you want to detect on.</li>\n      </ol>\n      \n<div class=\"figure\">\n<div class=\"modal-mock\" style=\"max-width:640px;margin:0 auto;\">\n  <div class=\"modal-head\">Event Settings <span>&times;</span></div>\n  <div class=\"modal-body\">\n    <div class=\"form-grid\" style=\"grid-template-columns:90px 1fr 90px;margin-bottom:10px;\">\n      <span>Event Type</span><input value=\"Intrusion Detection\" disabled>\n      <span></span>\n      <span></span><select disabled style=\"outline:2px solid #d64545;\"><option>CH 1</option><option>CH 2</option><option>CH 3</option><option>CH 4</option><option>CH 5</option><option>CH 6</option><option>CH 7</option></select>\n      <span class=\"btn small primary\">+ Add Item</span>\n    </div>\n    <div style=\"height:220px;background:linear-gradient(135deg,#4a5568,#2d3748);border-radius:6px;position:relative;overflow:hidden;\">\n      <svg width=\"100%\" height=\"100%\" viewBox=\"0 0 500 220\"><polygon points=\"90,90 300,90 320,220 60,220\" fill=\"rgba(240,220,60,0.25)\" stroke=\"#f0dc3c\" stroke-width=\"2\"/><circle cx=\"90\" cy=\"90\" r=\"5\" fill=\"#fff\" stroke=\"#f0dc3c\" stroke-width=\"2\"/><circle cx=\"300\" cy=\"90\" r=\"5\" fill=\"#fff\" stroke=\"#f0dc3c\" stroke-width=\"2\"/><circle cx=\"320\" cy=\"220\" r=\"5\" fill=\"#fff\" stroke=\"#f0dc3c\" stroke-width=\"2\"/><circle cx=\"60\" cy=\"220\" r=\"5\" fill=\"#fff\" stroke=\"#f0dc3c\" stroke-width=\"2\"/></svg>\n    </div>\n  </div>\n  <div class=\"modal-foot\" style=\"justify-content:flex-start;\"><span style=\"font-size:11px;color:var(--text-muted);\">00:00 &nbsp;&#9654;&#9646;&#9646; &nbsp; 00:26</span></div>\n</div>\n<figcaption>Setting the detection zone on the reference video</figcaption>\n</div>\n\n      <p>Please refer to the video to set the detection area appropriately. The detection area can be configured using the features below. Or, using Import Area Info, you can select area information created in another event's settings.</p>\n      <ul class=\"steps\">\n        <li>Dragging inside the detection area <strong>moves</strong> the entire area.</li>\n        <li>Dragging a vertex <strong>moves</strong> that vertex.</li>\n        <li>Clicking the yellow line of the detection area <strong>adds</strong> a new vertex.</li>\n        <li>Right-clicking a vertex <strong>deletes</strong> it.</li>\n        <li>Drag the transparent gray rectangle to set the <strong>label position</strong>.</li>\n      </ul>\n      <p>Once you finish configuring, the area and label you set are displayed on the video like this:</p>\n      \n<div class=\"figure\" style=\"max-width:480px;\">\n  <div style=\"height:220px;background:linear-gradient(135deg,#5b6b73,#33424a);border-radius:6px;position:relative;\">\n    <svg width=\"100%\" height=\"100%\" viewBox=\"0 0 480 220\"><polygon points=\"150,70 330,70 300,190 120,190\" fill=\"none\" stroke=\"#f0dc3c\" stroke-width=\"2\"/>\n    <rect x=\"200\" y=\"130\" width=\"16\" height=\"20\" fill=\"rgba(255,0,0,0.5)\" stroke=\"red\"/>\n    <rect x=\"180\" y=\"60\" width=\"120\" height=\"20\" fill=\"rgba(0,0,0,0.6)\"/><text x=\"185\" y=\"75\" fill=\"#fff\" font-size=\"12\">Intrusion: 0</text></svg>\n  </div>\n  <figcaption>Configured zone and label shown on the video</figcaption>\n</div>\n\n      <ol start=\"3\">\n        <li>Configure each option, then click the <strong>Apply</strong> button to save.</li>\n      </ol>\n      \n<div class=\"figure\">\n<div class=\"app-panel\">\n  <div class=\"form-grid\" style=\"grid-template-columns:150px 1fr 140px 1fr;font-size:12.5px;\">\n    <span>Event Name</span><input value=\"Intrusion Detection\" disabled>\n    <span>Detection Policy</span><select disabled><option>Cautious Detection &#9432;</option></select>\n    <span>Event Count Label</span><input value=\"Intrusion\" disabled>\n    <span>Target Object</span><select disabled><option>Person &#9679;</option></select>\n    <span>Count Reset</span><span><select disabled style=\"width:80px;\"><option>00:00</option></select> <span class=\"btn small\">Reset</span></span>\n    <span>Ignore Repeat Object</span><input type=\"checkbox\" checked disabled> &#9432;\n    <span></span><span></span>\n    <span>Ignore Continuous Events</span><input type=\"checkbox\" disabled> &#9432;\n    <span></span><span></span>\n    <span>Re-alert Interval</span><span><input value=\"300\" disabled style=\"width:60px;\"> every sec &#9432;</span>\n    <span></span><span></span>\n    <span>Ignore Time</span><span><input value=\"3\" disabled style=\"width:60px;\"> every sec &#9432;</span>\n  </div>\n</div>\n</div>\n\n      <ul class=\"steps\">\n        <li><strong>Event Name</strong>: sets the name of the configured event area.</li>\n        <li><strong>Detection Policy</strong>: choose whether object judgment is fast or cautious. Cautious detection observes an object for a period of time to judge events more accurately and reduce false alarms, but the event fires relatively later. Fast detection minimizes observation time so the event fires as soon as detection occurs, but misidentification may occur.</li>\n        <li><strong>Event Count Label</strong>: sets the name of the event count label drawn on the video.</li>\n        <li><strong>Target Object</strong>: sets what the event should detect \u2014 person, vehicle, or two-wheeler.</li>\n        <li><strong>Count Reset</strong>: sets whether the event occurrence count value resets. When enabled, the count value resets at the configured time.</li>\n        <li><strong>Ignore Repeat Object</strong>: when checked, ignores a repeat entry into the event area by the same object.</li>\n        <li><strong>Ignore Continuous Events</strong>: when checked, ignores events from new objects while a previously detected object remains inside the event area.</li>\n        <li><strong>Re-alert Interval</strong>: when Ignore Continuous Events is enabled and a detected object remains inside the area, re-fires the event at the configured interval.</li>\n        <li><strong>Ignore Time</strong>: does not fire new events for a set period of time after an event occurs.</li>\n        <li><strong>Confidence Score Threshold</strong>: the confidence score is displayed for each object on the video when \"Confidence/Tracking ID\" is checked under Output &ndash; OSD. An event only fires when an object's confidence score exceeds the value set here. A lower value means similar-looking objects are also detected. Because the final event is judged through several stages of downstream algorithms, only adjust this value when truly necessary.</li>\n      </ul>\n\n      <h2>Action Settings</h2>\n      <p>The action settings define what happens when the configured event occurs.</p>\n      \n<div class=\"figure\">\n<div class=\"app-panel\">\n  <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:10px;\"><strong style=\"font-size:13px;\">Action Settings</strong> <span class=\"btn small\">+ Add</span></div>\n  <table class=\"app-table\">\n    <tr><th>Action Type</th><th>Action Name</th><th>Actions</th></tr>\n    <tr><td colspan=\"3\" style=\"text-align:center;color:var(--text-muted);\">\u2014</td></tr>\n  </table>\n</div>\n</div>\n\n      <ol>\n        <li>Click <strong>Add</strong> to add a new action item.</li>\n        <li>For the supported action types and how to configure them, see the <a href=\"#\">Action Setting Guide</a>. Configure each action you want to run when the event occurs.</li>\n      </ol>\n\n      <h2>Finishing Setup</h2>\n      <ol>\n        <li>Once you've finished configuring the event and action settings for the rule set, click the <strong>Save</strong> button at the very bottom to submit the intrusion detection event action settings.</li>\n      </ol>\n      <div class=\"figure\" style=\"max-width:120px;\"><span class=\"btn small primary\">Save</span></div>\n      <ol start=\"2\">\n        <li>If the settings were applied successfully, you can see the item in the list on the Intrusion Detection app screen.</li>\n      </ol>\n      \n<div class=\"figure\">\n<div class=\"app-panel\">\n  <div style=\"display:flex;align-items:center;margin-bottom:10px;\"><strong style=\"font-size:14px;\">Intrusion Detection (1)</strong> <span class=\"btn small primary\" style=\"margin-left:auto;\">&#8801;+ Add</span></div>\n  <table class=\"app-table\">\n    <tr><th>No</th><th>Name</th><th>Activation</th><th>Operation</th></tr>\n    <tr><td>1</td><td style=\"color:var(--blue);\">Hazardous Area Access</td><td><span style=\"background:#2653d6;border-radius:10px;width:34px;height:18px;display:inline-block;position:relative;\"><span style=\"position:absolute;right:2px;top:2px;width:14px;height:14px;background:#fff;border-radius:50%;\"></span></span></td><td>&#8942;</td></tr>\n  </table>\n</div>\n</div>\n\n\n      <h2>Filter Settings (Optional)</h2>\n      <p>You can use schedule and combined-rule filters to configure event filters that gate whether an action runs. The schedule and combined-rule filter settings described below are not required to build an action rule \u2014 configure them only if needed.</p>\n\n      <h2>Schedule Settings</h2>\n      <p>You can configure an event action schedule. Schedules run on a recurring basis and are used to set the time window in which an action should run when an event occurs.</p>\n      <ol>\n        <li>Click the <strong>Set</strong> button to configure an event action schedule.</li>\n      </ol>\n      \n<div class=\"figure\">\n<div class=\"app-panel\">\n  <div style=\"display:flex;align-items:center;margin-bottom:10px;\"><strong style=\"font-size:13px;\">Schedule Settings</strong> <span class=\"btn small\" style=\"margin-left:auto;\">Set</span></div>\n  <table class=\"app-table\">\n    <tr><th>Name</th><th>Actions</th></tr>\n    <tr><td colspan=\"2\" style=\"text-align:center;color:var(--text-muted);\">Always</td></tr>\n  </table>\n</div>\n</div>\n\n      <ol start=\"2\">\n        <li>For detailed instructions, see the <a href=\"#\">Schedule Setting Guide</a>. Add a schedule setting to gate when actions run in response to events.</li>\n      </ol>\n\n      <h2>Combined Rule Condition Settings</h2>\n      <ol>\n        <li>You can add combined conditions to event actions to perform more sophisticated event filtering. The items you can use as combined conditions are:\n          <ul class=\"steps\">\n            <li>Rules configured on event-action-type applications</li>\n            <li>Events that make up rules configured on event-action-type applications</li>\n            <li>System I/O devices such as Alarm In or Virtual Alarm In</li>\n          </ul>\n        </li>\n        <li>Click <strong>Add</strong> to configure a combined rule condition.</li>\n      </ol>\n      \n<div class=\"figure\">\n<div class=\"app-panel\">\n  <div style=\"display:flex;align-items:center;margin-bottom:10px;\"><strong style=\"font-size:13px;\">Combined Rule</strong> <span class=\"btn small\">+ Add</span></div>\n  <table class=\"app-table\">\n    <tr><th>UUID</th><th>NOT</th><th>Time Range</th><th>Actions</th></tr>\n    <tr><td colspan=\"4\" style=\"text-align:center;color:var(--text-muted);\">\u2014</td></tr>\n  </table>\n</div>\n</div>\n\n      <ol start=\"3\">\n        <li>For detailed instructions, see the <a href=\"#\">Combined Rule Condition Setting Guide</a>.</li>\n      </ol>";
